   378  void Leader::SendCommissioningSetResponse(const Coap::Message &    aRequest,
   379                                            const Ip6::MessageInfo & aMessageInfo,
   380                                            MeshCoP::StateTlv::State aState)
   381  {
   382      otError           error = OT_ERROR_NONE;
   383      Coap::Message *   message;
   384      MeshCoP::StateTlv state;
   385
   386      VerifyOrExit((message = MeshCoP::NewMeshCoPMessage(Get<Coap::Coap>())) != NULL, error = OT_ERROR_NO_BUFS);
   387
   388      SuccessOrExit(error = message->SetDefaultResponseHeader(aRequest));
   389      SuccessOrExit(error = message->SetPayloadMarker());
   390
   391      state.Init();
   392      state.SetState(aState);
   393      SuccessOrExit(error = message->AppendTlv(state));
   394
   395      SuccessOrExit(error = Get<Coap::Coap>().SendMessage(*message, aMessageInfo));
   396
   397      otLogInfoMeshCoP("sent commissioning dataset set response");
   398
   399  exit:
